import sys

def paint_cardiogram(n, a):
    total_width = sum(a)
    max_height = max(sum(a[:i+1]) for i in range(0, n, 2)) - min(sum(a[:i+1]) for i in range(1, n, 2))

    # Calculate the y-coordinates of the points
    y_coords = [0]
    for i in range(n):
        if i % 2 == 0:
            y_coords.append(y_coords[-1] + a[i])
        else:
            y_coords.append(y_coords[-1] - a[i])

    # Determine the range of x-coordinates for each y-coordinate
    x_ranges = []
    current_x = 0
    for i in range(n):
        if i % 2 == 0:
            x_ranges.append((current_x, current_x + a[i]))
        else:
            x_ranges.append((current_x + a[i], current_x))
        current_x += a[i]

    # Print the cardiogram
    for y in range(max_height, -max_height - 1, -1):
        line = [' '] * total_width
        for i in range(n):
            if i % 2 == 0:
                if y >= y_coords[i] and y < y_coords[i+1]:
                    start, end = x_ranges[i]
                    for x in range(start, end):
                        line[x] = '/'
            else:
                if y <= y_coords[i] and y > y_coords[i+1]:
                    start, end = x_ranges[i]
                    for x in range(end, start):
                        line[x] = '\\'
        print(''.join(line))

# Read input
